// Copy SVG markup of selected icon to clipboard
function copyIconSvg(name, style, pathD, cardEl) {
  const svgCode = '<svg width="20" height="20" viewBox="0 0 20 20" fill="none" xmlns="http://www.w3.org/2000/svg">\n  <path d="' + pathD + '" fill="currentColor"/>\n</svg>';
  navigator.clipboard.writeText(svgCode).then(() => {
    if (typeof window.showToast === 'function') {
      window.showToast('Tersalin: ' + name + ' (' + style + ') SVG!', 2200);
    } else {
      const toast = document.getElementById('copyToast');
      if (toast) {
        toast.textContent = 'Tersalin: ' + name + ' (' + style + ') SVG!';
        toast.classList.add('show');
        setTimeout(() => {
          toast.classList.remove('show');
          toast.textContent = 'Copied to clipboard!';
        }, 2200);
      }
    }
  }).catch(err => {
    console.error('Failed to copy SVG: ', err);
  });
}

// Initialize Icon Gallery Interactive Logic
function initIconGallery() {
  const iconGrid = document.getElementById('iconGrid');
  const iconSearch = document.getElementById('iconSearchInput');
  const filterBtns = document.querySelectorAll('.icon-gallery__filter-btn');
  const iconCountBadge = document.getElementById('iconCountBadge');

  if (!iconGrid) return;

  let currentFilter = 'all';
  let currentSearch = '';

  function renderIcons() {
    const filtered = iconsData.filter(icon => {
      const matchesFilter = currentFilter === 'all' || icon.style === currentFilter;
      const matchesSearch = !currentSearch || 
        icon.name.toLowerCase().includes(currentSearch) || 
        icon.kebab.toLowerCase().includes(currentSearch);
      return matchesFilter && matchesSearch;
    });

    if (iconCountBadge) {
      iconCountBadge.textContent = 'Menampilkan ' + filtered.length + ' ikon (Klik ikon untuk salin SVG)';
    }

    iconGrid.innerHTML = filtered.map(icon => `
      <div class="icon-gallery__card" onclick="copyIconSvg('${icon.kebab}', '${icon.style}', '${icon.d}', this)" title="Klik untuk salin SVG code ${icon.name} (${icon.style})">
        <div class="icon-gallery__preview">
          <svg width="20" height="20" viewBox="0 0 20 20" fill="none">
            <path d="${icon.d}" fill="currentColor"/>
          </svg>
        </div>
        <span class="icon-gallery__name">${icon.name}</span>
        <span class="icon-gallery__badge icon-gallery__badge--${icon.style}">${icon.style}</span>
      </div>
    `).join('');
  }

  if (iconSearch) {
    iconSearch.addEventListener('input', (e) => {
      currentSearch = e.target.value.trim().toLowerCase();
      renderIcons();
    });
  }

  filterBtns.forEach(btn => {
    btn.addEventListener('click', () => {
      filterBtns.forEach(b => b.classList.remove('is-active'));
      btn.classList.add('is-active');
      currentFilter = btn.getAttribute('data-filter');
      renderIcons();
    });
  });

  renderIcons();
}

// Expose iconsData and copyIconSvg globally
window.iconsData = iconsData;
window.copyIconSvg = copyIconSvg;
window.initIconGallery = initIconGallery;

// Auto-initialize when DOM is ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initIconGallery);
} else {
  initIconGallery();
}
